entries[45589] = { ["name"] = "Roboschreiter aus Gnomeregan", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Roboschreiter aus Gnomeregan oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wenn Ihr definitiv, unbedingt sofort dort sein müsst. - Rillie Spindelnuss\"\nVerkäufer:\nRillie Spindelnuss\nZone:\nEiskrone\nKosten:\n100" }
entries[45590] = { ["name"] = "Elekk aus der Exodar", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Elekk aus der Exodar oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Elekks aus der Exodar erhielten den Segen von O'ros, dem Naaru, der mit Velen und seinen Gefolgsleuten von Draenor nach Azeroth gezogen ist.\"\nVerkäufer:\nIrisee\nZone:\nEiskrone\nKosten:\n100" }
entries[45591] = { ["name"] = "Darnassischer Nachtsäbler", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren darnassischen Nachtsäbler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wenn das Reittier eines Nachtelfen stirbt, behält dessen Reiter traditionell einen seiner großen Fangzähne als Erinnerungsstück.\"\nVerkäufer:\nRook Falkenfaust\nZone:\nEiskrone\nKosten:\n100" }
entries[45592] = { ["name"] = "Kodo aus Donnerfels", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Kodo aus Donnerfels oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Als Alpha seiner Herde ist dieser Kodo ein Paradebeispiel für diese mächtigen Kreaturen, die durch Mulgore donnern.\"\nVerkäufer:\nDoru Donnerhorn\nZone:\nEiskrone\nKosten:\n100" }
entries[45593] = { ["name"] = "Raptor der Dunkelspeere", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Raptor der Dunkelspeere oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese Raptorenart wurde ursprünglich von den Drakkari gezüchtet, doch ist mittlerweile vom Dunkelspeerstamm in Nordend übernommen worden.\"\nVerkäufer:\nSamamba\nZone:\nEiskrone\nKosten:\n100" }
entries[45594] = { ["name"] = "Beinplatten der endlosen Leere", ["text"] = "Wird beim Aufheben gebunden\nBeine Platte\n14 Rüstung\n+4 [Stärke oder Intelligenz]\n+5 Ausdauer\n+ 4 Ausweichen\n+ 3 Parieren\n\nPrismatischer Sockel\nPrismatischer Sockel\nPrismatischer Sockel\nSockelbonus: + 2 Ausdauer\n\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
entries[45595] = { ["name"] = "Wolf aus Orgrimmar", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Worg aus Orgrimmar oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Kurze Zeit lang ließen viele Orcs verlauten, dass sie \"hungrig wie ein Wolf aus Orgrimmar\" wären. Einige Blutelfen nutzen den Spruch noch immer voller Ironie.\"\nVerkäufer:\nFreka Blutaxt\nZone:\nEiskrone\nKosten:\n100" }
entries[45596] = { ["name"] = "Falkenschreiter aus Silbermond", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Falkenschreiter aus Silbermond oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ich sag nur, ich hätte heute Lust auf Hühnchen. Plötzlich liege ich mit dem Rücken auf dem Boden und das Viech versucht herauszufinden, wie meine Augen schmecken. - Stümpi Sprengbolz\"\nVerkäufer:\nTrellis Morgensonne\nZone:\nEiskrone\nKosten:\n100" }
entries[45597] = { ["name"] = "Schlachtross der Verlassenen", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares Schlachtross der Verlassenen oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wenn gefallene Helden in den Untod erweckt werden, folgen ihnen auch ihre Pferde.\"\nVerkäufer:\nEliza Killian\nZone:\nEiskrone\nKosten:\n100" }
