entries[45693] = { ["name"] = "Mimirons Kopf", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren mechanischen Gnomenkopf oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein Beispiel titanischer Handwerkskunst, wie sie vom Alten Gott Yogg-Saron gesammelt wurde. Derzeit der größte mechanische Gnomenkopf in ganz Azeroth.\"\nBeute von:\nYogg-Saron\nOrt:\nUlduar" }
