entries[46097] = { ["name"] = "Liebkosung des Wahnsinns", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n5 - 7 Schaden Geschwindigkeit 2.60\n(2.3 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 1.\n\nPrismatischer Sockel\nSockelbonus: + 1 Angriffskraft\n\nHaltbarkeit 110 / 110\nVerkaufspreis:" }
entries[46098] = { ["name"] = "Waffe - Blutsauger", ["text"] = "Benutzen: Eine Waffe dauerhaft verzaubern, sodass sie manchmal bei einem erzielten Treffer oder verursachtem Blutungsschaden den Effekt 'Blutreserve' gewährt. Wenn Eure Gesundheit unter 35% sinkt, stellt 'Blutreserve' 14665 Gesundheit wieder her. Hält 20 Sek. lang an und ist 5-mal stapelbar. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:" }
entries[46099] = { ["name"] = "Horn des schwarzen Wolfs", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren schwarzen Wolf oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Heult laut genug, um meilenweit gehört zu werden.\"\nVerkäufer:\nWeltverkäufer\nKosten:" }
entries[46100] = { ["name"] = "Weißer Kodo", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren weißen Kodo oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Kodos sind das Rückgrat unseres Volks. Wohin die Horde auch zieht - zum Handel, zur Besiedlung oder in den Krieg - man wird dort immer den mächtigen Kodo erblicken.\" - Harb Klauenhuf\nVerkäufer:\nHarb Klauenhuf\nZone:\nMulgore\nKosten:" }
entries[46101] = { ["name"] = "Blaues Skelettschlachtross", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares blaues Skelettpferd oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Ein seltener Anblick. Die meisten sind verschwunden, als Baron Totenschwur in Stratholme regiert hat.\"\nKlassisch" }
entries[46102] = { ["name"] = "Pfeife des Gifthautravasaurus", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Gifthautravasaurus oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Ihr habt dieses Viech aus einem schuppigen Welpen aufgezogen. Mor'vek würde so stolz sein. Dennoch würde er Euch den Dreck sauber machen lassen, den es in der Ecke hinterlassen hat.\"\nQuest:\nSie werden so schnell erwachsen\nZone:\nKrater von Un'Goro" }
entries[46106] = { ["name"] = "Argentumlanze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand\n1 - 2 Schaden Geschwindigkeit 3.00\n(0.5 Schaden pro Sekunde)\nHaltbarkeit 16 / 16\nVerkaufspreis:" }
entries[46108] = { ["name"] = "Technik: Rituale des Neumonds", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Rituale des Neumonds schreibt.\nBenötigt Inschriftenkunde von Nordend (1)\nVerkaufspreis:\nRituale des Neumonds\nWird beim Anlegen gebunden\nIn Schildhand geführt\n+6 Intelligenz\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nBenutzen: Verwandelt Euch in einen riesigen Wolf. (10 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Leichtes Pergament (10), Meerestinte (5), Äonenschatten (3)\nOptionale Reagenzien: [] (#49)" }
entries[46109] = { ["name"] = "Meeresschildkröte", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man eine Meeresschildkröte beschwört. Dieses Reittier ist an Land nicht besonders flink, aber ein großartiger Schwimmer.\nBeschwört eine reitbare Meeresschildkröte und gibt sie wieder frei. Dieses Reittier ist an Land nicht besonders flink, aber ein großartiger Schwimmer.\n\nDurch ihre ausdauernde und zähe Natur wird ihre Schwimmgeschwindigkeit durch Effekte, die Eure Reitgeschwindigkeit verringern oder erhöhen, nicht verändert.\n80 ( 80)\n\n\"Diese Reittiere fühlen sich im Wasser deutlich wohler als an Land und werden häufig in jungem Alter von Fischern gefangen.\"\nBeruf:\nAngeln" }
entries[46110] = { ["name"] = "Alchemistenbeutel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie von Nordend\n(50)\n<Zum Öffnen rechtsklicken>\nVerkaufspreis:" }
