entries[46345] = { ["name"] = "Armschienen der gerechten Reformation", ["text"] = "Wird beim Aufheben gebunden\nHandgelenk Platte\n8 Rüstung\n+2 [Stärke oder Intelligenz]\n+3 Ausdauer\nErhöht Eure Tempowertung um + 2.\n+ 3 Vielseitigkeit\n\nPrismatischer Sockel\nSockelbonus: + 1 Intelligenz\n\nHaltbarkeit 55 / 55\nVerkaufspreis:" }
entries[46346] = { ["name"] = "Stiefel der unruhigen Beute", ["text"] = "Wird beim Aufheben gebunden\nFüße Kette\n6 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 2.\nHaltbarkeit 80 / 80\nVerkaufspreis:" }
entries[46347] = { ["name"] = "Umhang der schlummernden Flamme", ["text"] = "Wird beim Aufheben gebunden\nRücken\n3 Rüstung\n+2 Intelligenz\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\n+ 3 Vielseitigkeit\nVerkaufspreis:" }
entries[46348] = { ["name"] = "Formel: Waffe - Blutsauger", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Blutsauger' durchführt.\nEine Waffe dauerhaft verzaubern, sodass sie manchmal bei einem erzielten Treffer oder verursachtem Blutungsschaden den Effekt 'Blutreserve' gewährt. Wenn Eure Gesundheit unter 35% sinkt, stellt 'Blutreserve' 14665 Gesundheit wieder her. Hält 20 Sek. lang an und ist 5-mal stapelbar. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Verzauberkunst von Nordend (75)\nVerkaufspreis:" }
entries[46350] = { ["name"] = "Säule der Seelenstärke", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n4 - 6 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\n+18 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\n+ 5 Vielseitigkeit\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
entries[46351] = { ["name"] = "Blutzermalmerknüppel", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n5 - 7 Schaden Geschwindigkeit 2.60\n(2.3 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 2.\nHaltbarkeit 110 / 110\nVerkaufspreis:" }
entries[46352] = { ["name"] = "Geschenk der Erde", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Wählt einen Lavafelsspalt an, um das Geschenk der Erde zu kanalisieren und ihn zu füllen. Es dauert 1,5 Sek., die Macht von Kern vollständig zu beschwören. (5 Sek. Abklingzeit)" }
