entries[46376] = { ["name"] = "Fläschchen des Frostwyrms", ["text"] = "Benutzen: Erhöht die Zaubermacht 1 Stunde lang um 17 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
