entries[46378] = { ["name"] = "Fläschchen des reinen Mojo", ["text"] = "Benutzen: Erhöht Eure Vielseitigkeit 1 Stunde lang um 17 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[46379] = { ["name"] = "Fläschchen des Steinbluts", ["text"] = "Benutzen: Erhöht 1 Stunde lang die maximale Gesundheit um 49 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
