entries[46382] = { ["name"] = "Silithidenei", ["text"] = "Questgegenstand\nBenutzen: Füttert das Gifthautjunge mit dem Silithidenei." }
entries[46384] = { ["name"] = "Verwertbare Grauflossentrümmer", ["text"] = "Questgegenstand\n\"Sie sind schäbig und kaputt. Allerdings sehen so auch die meisten Hütten der Murlocs aus...\"" }
entries[46385] = { ["name"] = "Mirakulöses mobiles Murloc-Motel mit Meerblick", ["text"] = "Questgegenstand\nBenutzen: Baut eine Murlochütte an einem spezifizierten Ort westlich von Wirrbarts Ausgrabung. (10 Sek. Abklingzeit)" }
entries[46386] = { ["name"] = "Schlammverkrustete uralte Scheibe", ["text"] = "Questgegenstand\n\"Obwohl dreckverkrustet, sind auf der geätzten Metallscheibe keinerlei Korrosionsspuren zu finden.\"" }
entries[46387] = { ["name"] = "Uraltes geschlitztes Gerät", ["text"] = "Questgegenstand\n\"Überzogen mit äonenalten Matschverkrustungen, ist es ein Rätsel, wie die inneren Mechanismen dieses Artefakts funktionieren.\"" }
entries[46388] = { ["name"] = "Detektor für vergrabene Artefakte", ["text"] = "Questgegenstand\nBenutzen: Findet in der Nähe vergrabene Artefakte.\n\"Eine schwere, korrodierte Batterie, die nachlässig mit einer großen Metallschüssel verbunden ist.\"" }
entries[46389] = { ["name"] = "Elunes Träne", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Im Mondbrunnen der Reinheit am südöstlichen Fuß des Donnergipfels im Eschental läutern." }
entries[46390] = { ["name"] = "Korrodierte Schlüssel", ["text"] = "\"Die Zacken der Schlüsselbärte sind alle abgebrochen.\"\nVerkaufspreis:" }
entries[46391] = { ["name"] = "Kaputte Uhr", ["text"] = "\"Die Zeiger zeigen noch immer die Zeit an, zu der die Dunkelküste zerrissen wurde.\"\nVerkaufspreis:" }
entries[46392] = { ["name"] = "Hirschsteak", ["text"] = "Questgegenstand\nBenutzen: Stellt im Verlauf von 24 Sek. ( 38 * 24 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 2 Ausdauer und Vielseitigkeit." }
entries[46395] = { ["name"] = "Unglücksbringende Hasenpfote", ["text"] = "Questgegenstand" }
entries[46396] = { ["name"] = "Pfeife des Wolvarwaisenkindes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Das Waisenkind rufen und fortschicken, dessen Beaufsichtigung Ihr während der Kinderwoche übernommen habt.\nBenötigt Kinderwoche" }
