entries[46543] = { ["name"] = "Leiche einer lachenden Schwester", ["text"] = "Questgegenstand\nEinzigartig (10)\n\"Sie sind überraschend leicht.\"" }
entries[46544] = { ["name"] = "Neugieriger Wolvarwelpe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick einen neugierigen Wolvarwelpen beschwören oder wieder freigeben.\n80 ( 80)" }
