entries[46693] = { ["name"] = "Kleiner Papierzeppelin", ["text"] = "Questgegenstand\nBenutzen: Wirft den Zeppelin Eurem Waisen aus Nordend zu. (15 Sek. Abklingzeit)\nBenötigt Kinderwoche\n\"Genau die richtige Größe für ein kleines Kind.\"\nVerkaufspreis:" }
entries[46694] = { ["name"] = "Dellylahs gestohlene Bohnen", ["text"] = "Questgegenstand" }
entries[46695] = { ["name"] = "Smaragdgrüne Schriftrolle", ["text"] = "Questgegenstand" }
entries[46696] = { ["name"] = "Pantherfigur", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: In einen pirschenden Panther verwandeln, unaufspürbar für die meisten Gegner." }
entries[46697] = { ["name"] = "Geschwollener Giftbeutel", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest." }
