entries[46699] = { ["name"] = "Dellylahs gestohlenes Wasser", ["text"] = "Questgegenstand" }
entries[46700] = { ["name"] = "Melithars gestohlene Taschen", ["text"] = "Questgegenstand" }
entries[46701] = { ["name"] = "Twidels improvisierter Sprengstoff", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Wirft Twidels improvisierten Sprengstoff auf den liegengebliebenen Wagen in Höllschreis Wacht." }
entries[46702] = { ["name"] = "Uraltes Gerätefragment", ["text"] = "Questgegenstand\nEinzigartig (5)\nBenutzen: Kombiniert 5 Artefaktfragmente miteinander zu einem uralten geschlitzten Artefakt.\n\"Verkrustet mit äonenalten Ablagerungen und erst vor Kurzem zerbrochen.\"" }
entries[46703] = { ["name"] = "Messingknopf", ["text"] = "\"Ein uraltes Modell mit einem silbernen Flügelemblem.\"\nVerkaufspreis:" }
entries[46707] = { ["name"] = "Kleiner rosafarbener Dickhäuter", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick ein kleinen rosafarbenen Dickhäuter beschwören oder wieder freigeben.\n80 ( 80)" }
entries[46708] = { ["name"] = "Frostwyrm des tödlichen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Frostwyrm des tödlichen Gladiators oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese wiederbelebten Bringer der Vernichtung fürchten sich nicht vor dem Tod, sie verbreiten ihn.\"\nKlassisch" }
entries[46709] = { ["name"] = "MiniZep-Steuerung", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört und kontrolliert Euren MiniZep. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[46710] = { ["name"] = "Rezept: Totenspeise", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Totenspeise backt.\nBenötigt Klassische Kochkunst (1)\nBenötigt Tag der Toten\nVerkaufspreis:\nTotenspeise\nBenutzen: Stellt im Verlauf von 25 Sek. ( 630000 / 5 * 25) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\nBenötigt Tag der Toten\nVerkaufspreis:\nBenötigt Herkömmliches Mehl , Eiskalte Milch" }
entries[46711] = { ["name"] = "Seelenkerze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert eine Seelenkerze, welche die Willenskraft aller in der Nähe um 4 erhöht. (5 Min Abklingzeit)\nBenötigt Tag der Toten\nVerkaufspreis:" }
entries[46714] = { ["name"] = "Halgas 'Straßenfeger'", ["text"] = "Questgegenstand\n\"Die Läufe dieser monströsen Waffe sind fast so dick wie Eure Faust. Sie kann nur von einem Karawanenkodo aus angewendet werden.\"" }
entries[46715] = { ["name"] = "Geheiligte Mondsteine", ["text"] = "Questgegenstand\nEinzigartig\n\"Der Glanz von Elunes Anmut scheint durch.\"" }
entries[46716] = { ["name"] = "Zornwurzelsamen", ["text"] = "Questgegenstand\nBenutzen: Lässt Wurzeln das Ziel würgen, bis es tot ist. Wirkt nur bei Teufelsfelsgrellkin." }
entries[46718] = { ["name"] = "Orangefarbene Ringelblumen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt 30 Sek. lang Entdeckung geringer Unsichtbarkeit. Wirkt nur am Tag der Toten. (30 Sek. Abklingzeit)\nBenötigt Tag der Toten\n\"Zieht angeblich Geister an und hilft dabei, am Tag der Toten mit den Seelen der Verstorbenen zu kommunizieren.\"\nVerkaufspreis:" }
entries[46720] = { ["name"] = "Shael'dryns Totstelltechnik", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Stellt sich tot, wodurch andere erfolgreich verwirrt werden können. Hält 6 Min. lang an. Funktioniert nur im Schattenwinkel. (2 Sek., 500 Ms Abklingzeit)" }
entries[46721] = { ["name"] = "Dartols Rute", ["text"] = "Questgegenstand\nEinzigartig\n\"Die zusammengesetzte Rute fühlt sich in Eurer Hand gleichzeitig schwer und leicht an.\"" }
entries[46722] = { ["name"] = "Grol'doms Netz", ["text"] = "Questgegenstand\nBenutzen: Wirft ein Netz auf einen Plünderer der Klingenmähnen in einem Umkreis von 15 Metern. (10 Sek. Abklingzeit)" }
entries[46723] = { ["name"] = "Pilgerhut", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nKopf Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[46725] = { ["name"] = "Rotes Erbsengewehr", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Feuert eine (größtenteils) harmlose Trockenerbse ab.\n200 Aufladungen\n\"Das einzig wahre Luftdruckgewehr mit 200 Schuss Erbsenmunition, in roter Sonderedition!\"\nVerkaufspreis:" }
entries[46726] = { ["name"] = "Gefesselter Klingenmähneneber", ["text"] = "\"Er ist bewußtlos. Ihr habt ihm wirklich eine reingehauen.\"" }
entries[46734] = { ["name"] = "Schlachttriagenverbandsset", ["text"] = "Questgegenstand" }
entries[46735] = { ["name"] = "Synthebräubrille", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nKopf Kosmetisch\nAnlegen: Diese Brille simuliert die Effekte von Alkohol. Die Effekte können leicht entfernt werden, indem man die Brille absetzt.\n\"Die Brille, sie tut irgendetwas!\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[46739] = { ["name"] = "Dartols Rute", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Verwandelt Euch bis Abbruch lang in einen Furbolg. Kann nur im Eschental benutzt werden. (10 Sek. Abklingzeit)" }
entries[46740] = { ["name"] = "Winterhauchgeschenk", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[46741] = { ["name"] = "Furbolgohr", ["text"] = "Questgegenstand" }
entries[46742] = { ["name"] = "Gestohlenes Getreide", ["text"] = "Questgegenstand" }
entries[46743] = { ["name"] = "Schneller purpurfarbener Raptor", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren schnellen purpurfarbenen Raptor oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Diese Dschungeljäger sind schon lange mit den Trollen verbündet und haben eine enge Bindung zu ihren Herren aufgebaut. Sie sind zum Reittier, Beschützer und Freund geworden.\"\nVerkäufer:\nSamamba\nZone:\nEiskrone\nKosten:" }
entries[46744] = { ["name"] = "Schneller Mondsäbler", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren schnellen Mondsäbler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Viele Nachtelfen verehren diese stolzen Reittiere, da deren schimmernde Felle für sie Elune, die Göttin des Mondes, symbolisieren.\"\nVerkäufer:\nRook Falkenfaust\nZone:\nEiskrone\nKosten:" }
