entries[46813] = { ["name"] = "Hippogryph des Silberbunds", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Hippogryphen des Silberbunds oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Der Silberbund\n- Ehrfürchtig\n\n\"Hippogryphen des Silberbunds sind ihren Reitern und der Allianz absolut treu ergeben.\"\nVerkäufer:\nHiren Lehrensang\nZone:\nEiskrone\nFraktion:\nDer Silberbund - Ehrfürchtig\nKosten:\n150" }
entries[46814] = { ["name"] = "Drachenfalke der Sonnenhäscher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Drachenfalken der Sonnenhäscher oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Die Sonnenhäscher\n- Ehrfürchtig\n\n\"Die Sonnenhäscher von Dalaran erwählen nur die flinksten und beachtlichsten Drachenfalken als ihre Reittiere.\"\nVerkäufer:\nVasarin Morgenröte\nZone:\nEiskrone\nFraktion:\nDie Sonnenhäscher - Ehrfürchtig\nKosten:\n150" }
entries[46815] = { ["name"] = "Streitross der Quel'dorei", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares Streitross der Quel'dorei oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Der Silberbund\n- Ehrfürchtig\n\n\"Stammt von einer Familie edler Pferde ab, die an den Ufern des Brunnens der Ewigkeit gegrast haben.\"\nVerkäufer:\nHiren Lehrensang\nZone:\nEiskrone\nFraktion:\nDer Silberbund - Ehrfürchtig\nKosten:\n100" }
entries[46816] = { ["name"] = "Falkenschreiter der Sonnenhäscher", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Falkenschreiter der Sonnenhäscher oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Die Sonnenhäscher\n- Ehrfürchtig\n\n\"Ich erwarte Geschwindigkeit, Anmut und Disziplin auf dem Schlachtfeld. Das hier sollte meine Erwartungen erfüllen. - Eressea Morgensänger\"\nVerkäufer:\nVasarin Morgenröte\nZone:\nEiskrone\nFraktion:\nDie Sonnenhäscher - Ehrfürchtig\nKosten:\n100" }
