entries[46887] = { ["name"] = "Reichhaltiges Festmahl", ["text"] = "Benutzen: Richtet ein reichhaltiges Festmahl her, das eine sehr hungrige Gruppe sättigen kann. Stellt im Verlauf von 20 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang Angriffskraft, Zaubermacht und Ausdauer.\nBenötigt Kochkunst der Scherbenwelt (50)\nBenötigt Pilgerfreudenfest\nVerkaufspreis:" }
entries[46888] = { ["name"] = "Reichhaltiger Korb", ["text"] = "Benutzen: Kombiniert Gewürzbrotfüllung, kandierte Süßkartoffeln, Moosbeerenchutney, Kürbiskuchen und einen langsam gerösteten Truthahn, um ein reichhaltiges Festmahl zu kreieren. Köstlich!\nBenötigt Kochkunst der Scherbenwelt (50)\nBenötigt Pilgerfreudenfest\nVerkaufspreis:" }
